# The equation to check is: a^3 (b^3 + c^3) = 2012 * (abc + 2)
# With a = 2, the equation simplifies to:
# 8 * (b^3 + c^3) = 2012 * (2*b*c + 2)
# 8 * (b^3 + c^3) = 4024 * (bc + 1)
# Dividing by 8:
# b^3 + c^3 = 503 * (bc + 1)

def check_solution(b, c):
    lhs = b**3 + c**3
    rhs = 503 * (b * c + 1)
    return lhs == rhs

solutions = []
# Constraints: a=2, 2 <= b <= 19, b <= c <= 19
for b in range(2, 20):
    for c in range(b, 20):
        if check_solution(b, c):
            solutions.append((2, b, c))

print("Solutions found for a=2:")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found.")
